/** Lazy loader for the bundled locale dictionaries.
 *
 *  Each locale is a separate chunk, so opening the dashboard in English never
 *  downloads the other languages. Arabic is hand-written and lives in
 *  `../dict`; everything here is generated by scripts/build_locales.py.
 */
export async function loadLocale(code: string): Promise<Record<string, string>> {
  switch (code) {
    case "de":
      return (await import("./de")).DE;
    case "es":
      return (await import("./es")).ES;
    case "fr":
      return (await import("./fr")).FR;
    case "hi":
      return (await import("./hi")).HI;
    case "ja":
      return (await import("./ja")).JA;
    case "pt":
      return (await import("./pt")).PT;
    case "ru":
      return (await import("./ru")).RU;
    case "zh":
      return (await import("./zh")).ZH;
    default:
      return {};
  }
}
